import json
from pathlib import Path
from .models import FunctionInfo


def load_coverage_report(coverage_path: Path) -> dict:
    """Load a JSON report generated by `coverage json`."""
    if not coverage_path.exists():
        return {}
    try:
        return json.loads(coverage_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {}


def compute_function_coverage(
    func: FunctionInfo,
    repo: Path,
    coverage_data: dict,
) -> tuple[int, int, list[int]]:
    """Return (untested_count, total_executable_lines, sorted_missing_line_numbers)."""
    rel_path = str(Path(func.file_path).relative_to(repo))
    file_entry = coverage_data.get("files", {}).get(rel_path)
    body_lines = set(range(func.body_start, func.end_lineno + 1))

    if not file_entry:
        # File never ran during tests at all
        missing_sorted = sorted(body_lines)
        return len(missing_sorted), len(missing_sorted), missing_sorted

    missing_set = set(file_entry.get("missing_lines", []))
    executed_set = set(file_entry.get("executed_lines", []))

    untested_in_func = sorted(body_lines & missing_set)
    total_tracked = len(body_lines & (executed_set | missing_set))

    return len(untested_in_func), total_tracked, untested_in_func
